import { useState } from 'react';
import { JxButton, JxInput } from '@jinx-ui/react';

export type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationFormProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_FIELDS: Array<[keyof RegistrationData, string]> = [
  ['name', 'Имя'],
  ['email', 'Email'],
  ['phone', 'Телефон'],
  ['country', 'Страна'],
  ['city', 'Город'],
  ['street', 'Улица, дом'],
  ['zip', 'Индекс'],
];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY);

  const update = (key: keyof RegistrationData) => (value: string) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const isLast = step === STEPS.length - 1;

  return (
    <section
      aria-label="Регистрация"
      style={{ display: 'grid', gap: 'var(--jx-space-6)' }}
    >
      <ol
        aria-label="Шаги регистрации"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-4)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((title, index) => (
          <li
            key={title}
            aria-current={index === step ? 'step' : undefined}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--jx-space-2)',
              color:
                index === step ? 'var(--jx-color-fg)' : 'var(--jx-color-fg-muted)',
            }}
          >
            <span
              aria-hidden="true"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: 'var(--jx-space-6)',
                height: 'var(--jx-space-6)',
                borderRadius: 'var(--jx-radius-full)',
                border: '1px solid currentColor',
              }}
            >
              {index + 1}
            </span>
            <span>{title}</span>
          </li>
        ))}
      </ol>

      <div style={{ display: 'grid', gap: 'var(--jx-space-4)' }}>
        {step === 0 && (
          <>
            <JxInput
              label="Имя"
              value={data.name}
              onValueChange={update('name')}
              autoComplete="name"
            />
            <JxInput
              label="Email"
              type="email"
              value={data.email}
              onValueChange={update('email')}
              autoComplete="email"
            />
            <JxInput
              label="Телефон"
              type="tel"
              value={data.phone}
              onValueChange={update('phone')}
              autoComplete="tel"
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInput
              label="Страна"
              value={data.country}
              onValueChange={update('country')}
              autoComplete="country-name"
            />
            <JxInput
              label="Город"
              value={data.city}
              onValueChange={update('city')}
              autoComplete="address-level2"
            />
            <JxInput
              label="Улица, дом"
              value={data.street}
              onValueChange={update('street')}
              autoComplete="street-address"
            />
            <JxInput
              label="Индекс"
              value={data.zip}
              onValueChange={update('zip')}
              autoComplete="postal-code"
            />
          </>
        )}

        {step === 2 && (
          <dl style={{ display: 'grid', gap: 'var(--jx-space-3)', margin: 0 }}>
            {REVIEW_FIELDS.map(([key, label]) => (
              <div
                key={key}
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-4)',
                }}
              >
                <dt style={{ color: 'var(--jx-color-fg-muted)' }}>{label}</dt>
                <dd style={{ margin: 0 }}>{data[key] || '—'}</dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', gap: 'var(--jx-space-3)' }}>
        <JxButton
          variant="secondary"
          disabled={step === 0}
          onClick={() => setStep((prev) => prev - 1)}
        >
          Назад
        </JxButton>
        {isLast ? (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => setStep((prev) => prev + 1)}>
            Дальше
          </JxButton>
        )}
      </div>
    </section>
  );
}

